node <<'NODE'
const { createRequire } = require('node:module');
const { readFileSync, mkdirSync } = require('node:fs');
const path = require('node:path');
const runtime = path.join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(path.join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(path.join(runtime, 'linux.json'), 'utf8'));
(async () => {
  const browser = await chromium.launch(config.browser.launchOptions);
  const page = await browser.newPage({ viewport: { width: 1280, height: 720 } });
  const errors = [];
  page.on('pageerror', e => errors.push(e.message));
  await page.goto('http://127.0.0.1:3000/', { waitUntil: 'load' });
  const titleVisible = await page.locator('#startOverlay').evaluate(el => getComputedStyle(el).display !== 'none');
  await page.locator('#newGameBtn').click();
  await page.locator('[data-class="Scout"]').click();
  await page.locator('#createHeroBtn').click();
  const startHidden = await page.locator('#startOverlay').evaluate(el => getComputedStyle(el).display === 'none');
  const actionsVisible = await page.locator('#actionPanel').evaluate(el => el.classList.contains('show'));
  await page.keyboard.down('ArrowRight');
  await page.waitForTimeout(300);
  await page.keyboard.up('ArrowRight');
  const positionMoved = await page.evaluate(() => document.getElementById('heroBadge').textContent);
  await page.locator('#touchSave').click();
  const saved = await page.evaluate(() => !!localStorage.getItem('whisperwood-save'));
  await page.reload({ waitUntil: 'load' });
  await page.locator('#continueGameBtn').click();
  const continued = await page.locator('#startOverlay').evaluate(el => getComputedStyle(el).display === 'none');
  await page.locator('#touchInventory').click();
  const bagOpen = await page.locator('#inventoryPanel').evaluate(el => el.classList.contains('show'));
  mkdirSync('/tmp/opencode', { recursive: true });
  await page.screenshot({ path: '/tmp/opencode/whisperwood-latest.jpg', type: 'jpeg', quality: 78 });
  console.log(JSON.stringify({ titleVisible, startHidden, actionsVisible, positionMoved, saved, continued, bagOpen, errors }, null, 2));
  await browser.close();
})().catch(e => { console.error(e); process.exit(1); });
