node <<'NODE'
const { createRequire } = require('node:module');
const { readFileSync, mkdirSync } = require('node:fs');
const path = require('node:path');
const runtime = path.join(process.env.HOME, '.local/share/omgithub-playwright');
const req = createRequire(path.join(runtime, 'package.json'));
const { chromium } = req('playwright');
const config = JSON.parse(readFileSync(path.join(runtime, 'linux.json'), 'utf8'));
(async () => {
  const browser = await chromium.launch({ ...config.browser.launchOptions, headless: true });
  const page = await browser.newPage({ viewport: { width: 1280, height: 720 } });
  const errors = [];
  page.on('pageerror', e => errors.push(e.message));
  await page.goto('http://127.0.0.1:3000/', { waitUntil: 'load' });
  await page.evaluate(() => localStorage.removeItem('whisperwood-save'));
  await page.locator('#newGameBtn').click();
  await page.locator('[data-class="Scout"]').click();
  await page.locator('#createHeroBtn').click();
  await page.evaluate(() => { hero.x = elder.x; hero.y = elder.y + 30; });
  await page.keyboard.press('e');
  await page.locator('#dialogOverlay button').first().click();
  const accepted = await page.evaluate(() => questStage === 1);
  for (let i = 0; i < 4; i++) {
    await page.evaluate((idx) => { hero.x = slimes[idx].x - 25; hero.y = slimes[idx].y; }, i);
    for (let hit = 0; hit < 3; hit++) {
      await page.evaluate((idx) => attack(idx), i);
      await page.waitForTimeout(300);
    }
  }
  const cleared = await page.evaluate(() => questStage === 2 && slimes.every(s => !s.alive));
