  await page.keyboard.press('e');
  await page.locator('#dialogOverlay button').first().click();
  const rewarded = await page.evaluate(() => questStage === 3 && hero.xp >= 35 && hero.gold >= 40);
  await page.evaluate(() => { hero.x = chest.x - 25; hero.y = chest.y; });
  await page.keyboard.press('e');
  const chestLooted = await page.evaluate(() => chest.open && hero.inventory['🌿'] === 1);
  await page.locator('#touchSave').click();
  await page.reload({ waitUntil: 'load' });
  await page.locator('#continueGameBtn').click();
  const continuedStage = await page.evaluate(() => questStage);
  await page.screenshot({ path: '/tmp/opencode/whisperwood-latest.jpg', type: 'jpeg', quality: 78 });
  console.log(JSON.stringify({ accepted, cleared, rewarded, chestLooted, continuedStage, errors }, null, 2));
  await browser.close();
})().catch(e => { console.error(e); process.exit(1); });
